package de.ostms.lc.imports.api;
import de.ostms.lc.audit.service.AuditService;import de.ostms.lc.check.service.DocumentCheckService;import de.ostms.lc.document.service.DocumentExtractionService;import de.ostms.lc.imports.domain.SwiftImportRecord;import de.ostms.lc.imports.service.*;import de.ostms.lc.lc.domain.Amendment;import de.ostms.lc.swift.PrintedSwiftNormalizer;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.io.IOException;import java.util.List;
@RestController @RequestMapping("/api/imports") public class SwiftImportController{private final SwiftImportService service;private final SwiftImportHistoryService history;private final AuditService audit;private final DocumentExtractionService extraction;private final PrintedSwiftNormalizer normalizer;private final DocumentCheckService checks;public SwiftImportController(SwiftImportService s,SwiftImportHistoryService h,AuditService a,DocumentExtractionService e,PrintedSwiftNormalizer n,DocumentCheckService c){service=s;history=h;audit=a;extraction=e;normalizer=n;checks=c;}@PostMapping("/preview")public SwiftImportPreview preview(@RequestBody SwiftImportRequest r){return service.preview(r);}@PostMapping("/file-preview")public SwiftFilePreview filePreview(@RequestPart("file")MultipartFile file)throws IOException{if(file.isEmpty())throw new IllegalArgumentException("Die Datei ist leer.");if(file.getSize()>10*1024*1024)throw new IllegalArgumentException("Die Datei ist größer als 10 MB.");var result=extraction.extractFile(file.getBytes(),file.getOriginalFilename(),file.getContentType());if(result.text()==null||result.text().isBlank())throw new IllegalArgumentException("Aus dem PDF konnte kein Text erkannt werden.");String normalized=normalizer.normalize(result.text());SwiftImportRequest request=new SwiftImportRequest(file.getOriginalFilename(),normalized.isBlank()?result.text():normalized);return new SwiftFilePreview(request,service.preview(request),result.status());}@PostMapping public Object execute(@RequestBody SwiftImportRequest r,Authentication a){Object result=service.execute(r);audit.record(a,"SWIFT_IMPORTED","IMPORT",null,r.filename());if(result instanceof Amendment amendment){audit.record(a,"MT707_RECEIVED","LETTER_OF_CREDIT",amendment.getLetterOfCredit().getId(),"Amendment "+amendment.getAmendmentNumber()+" (offen)");}return result;}@GetMapping public List<SwiftImportRecord> recent(){return history.recent();}}
